<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\BelongsToMany; use Illuminate\Database\Eloquent\Relations\HasMany;
class Provider extends Model { protected $fillable=['user_id','bio','timezone','is_active']; protected function casts(): array { return ['is_active'=>'boolean']; } public function user(): BelongsTo { return $this->belongsTo(User::class); } public function services(): BelongsToMany { return $this->belongsToMany(Service::class)->withPivot(['price','is_active'])->withTimestamps(); } public function availabilities(): HasMany { return $this->hasMany(Availability::class); } public function blockedTimes(): HasMany { return $this->hasMany(BlockedTime::class); } public function appointments(): HasMany { return $this->hasMany(Appointment::class); } }
